/**
 * The Cloudflare Worker entry point: serves the Next.js app and runs the scheduled CPL sync.
 * `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
 */
// @ts-ignore: generated at build time
import { default as nextApp } from "./.open-next/worker.js";
import { useDatabase } from "./lib/db.ts";
import { syncAllTeams } from "./lib/cpl-schedule.ts";

export default {
  fetch: nextApp.fetch,

  async scheduled(_event, env, ctx) {
    useDatabase(env.DB);
    ctx.waitUntil(syncAllTeams());
  },
} satisfies ExportedHandler<CloudflareEnv>;
